38	import org.springframework.samples.petclinic.model.Pet;
39	import org.springframework.samples.petclinic.model.Visit;
40	import org.springframework.samples.petclinic.rest.advice.CityAtCapacityException;
41	import org.springframework.samples.petclinic.rest.advice.DailyOwnerLimitExceededException;
42	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerHouseholdException;
43	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerTelephoneException;
44	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
45	import org.springframework.samples.petclinic.rest.api.OwnersApi;
46	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
47	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
48	import org.springframework.samples.petclinic.rest.dto.PetDto;
49	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
50	import org.springframework.samples.petclinic.rest.dto.VisitDto;
