52	import org.springframework.samples.petclinic.service.ClinicService;
53	import org.springframework.security.access.prepost.PreAuthorize;
54	import org.springframework.web.bind.annotation.CrossOrigin;
55	import org.springframework.web.bind.annotation.RequestMapping;
56	import org.springframework.web.bind.annotation.RestController;
57	import org.springframework.web.util.UriComponentsBuilder;
58	
59	import jakarta.transaction.Transactional;
60	
61	/**
62	 * @author Vitaliy Fedoriv
63	 */
64	
65	@RestController
66	@CrossOrigin(exposedHeaders = "errors, content-type")
67	@RequestMapping("/api")
68	public class OwnerRestControllerV1 implements OwnersApi {
69	
70	    /** Dedicated audit logger; emits one line per successful owner create. */
71	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
72	
73	    private final ClinicService clinicService;
74	
75	    private final OwnerMapper ownerMapper;
76	
77	    private final PetMapper petMapper;
78	
79	    private final VisitMapper visitMapper;
80	
81	    public OwnerRestControllerV1(ClinicService clinicService,
82	                                 OwnerMapper ownerMapper,
83	                                 PetMapper petMapper,
84	                                 VisitMapper visitMapper) {
85	        this.clinicService = clinicService;
86	        this.ownerMapper = ownerMapper;
87	        this.petMapper = petMapper;
88	        this.visitMapper = visitMapper;
89	    }
90	
91	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
92	    @Override
93	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
94	        Collection<Owner> owners;
95	        if (lastName != null) {
96	            owners = this.clinicService.findOwnerByLastName(lastName);
97	        } else {
98	            owners = this.clinicService.findAllOwners();
99	        }
100	        if (owners.isEmpty()) {
101	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
102	        }
103	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
104	    }
105	
106	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
107	    @Override
108	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
109	        Owner owner = this.clinicService.findOwnerById(ownerId);
110	        if (owner == null) {
111	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
112	        }
113	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
119	        // Normalize the address up front so every downstream use (the required-field check,
120	        // household-duplicate detection, the shared household id and the stored/returned value)
121	        // works from the same canonical form.
122	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
123	        List<String> missingFields = new ArrayList<>();
124	        if (isBlank(ownerFieldsDto.getFirstName())) {
125	            missingFields.add("firstName");
126	        }
127	        if (isBlank(ownerFieldsDto.getLastName())) {
128	            missingFields.add("lastName");
129	        }
130	        // Reject an address that is blank once normalized (e.g. whitespace-only input).
131	        if (isBlank(normalizedAddress)) {
132	            missingFields.add("address");
133	        }
134	        if (isBlank(ownerFieldsDto.getCity())) {
135	            missingFields.add("city");
136	        }
137	        if (isBlank(ownerFieldsDto.getTelephone())) {
138	            missingFields.add("telephone");
139	        }
140	        if (!missingFields.isEmpty()) {
141	            throw new InvalidOwnerFieldsException(missingFields);
142	        }
143	        // Determine the effective registration date up front so every downstream use (the daily
144	        // create-limit, the stored value and anything derived from it such as the membership number's
145	        // year segment) works from the same business-day-adjusted date. The effective date is the
146	        // supplied value when present, otherwise the server's current date; a weekend date is rolled
147	        // forward to the following Monday.
148	        LocalDate effectiveRegistrationDate = ownerFieldsDto.getRegistrationDate() != null
149	            ? ownerFieldsDto.getRegistrationDate()
150	            : LocalDate.now();
151	        effectiveRegistrationDate = toBusinessDay(effectiveRegistrationDate);
152	        // Reject the request once the day's owner-creation limit is reached: when 100 or more owners
153	        // already carry this adjusted business day's registration date, no further owners may be
154	        // created for that day.
155	        int ownersRegisteredToday = countOwnersRegisteredOn(effectiveRegistrationDate);
156	        if (ownersRegisteredToday >= MAX_OWNERS_PER_DAY) {
157	            throw new DailyOwnerLimitExceededException(effectiveRegistrationDate);
158	        }
159	        // Flag a bulk signup once more than 80 owners have already been created for this
160	        // business day, sharing the same daily accumulation path as the create-limit rule above.
161	        boolean bulkSignupWarning = ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD;
162	        // Reject the request when the owner's city is already full: a city that already holds the
163	        // maximum of 50 owners (compared case-insensitively, as elsewhere) accepts no more.
164	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= MAX_OWNERS_PER_CITY) {
165	            throw new CityAtCapacityException(ownerFieldsDto.getCity());
166	        }
167	        // Normalize the telephone into E.164 form; a number that cannot form a valid
168	        // E.164 value is rejected with a 400.
169	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
170	        // Email is optional; when present it must be a syntactically valid address and is
171	        // stored lower-cased. An invalid address is rejected with a 400.
172	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
173	        // Reject the request if the E.164 telephone is already used by any other owner.
174	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
175	            .map(Owner::getTelephone)
176	            .filter(existing -> existing != null)
177	            .anyMatch(normalizedTelephone::equals);
178	        if (telephoneInUse) {
179	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
180	        }
181	        // Household handling for a matching last name + address (compared case-insensitively with
182	        // collapsed whitespace). By default such a request is rejected as a duplicate household;
183	        // when the caller opts in via 'sharesHousehold' the owner is instead admitted into the shared
184	        // household and every member (the new owner and any existing ones) is stamped with the same
185	        // stable 'householdId'.
186	        String normalizedLastName = collapse(ownerFieldsDto.getLastName());
187	        String householdId = null;
188	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
189	            householdId = householdId(normalizedLastName, normalizedAddress);
190	            // Backfill the shared identifier onto any existing member of this household so the whole
191	            // household carries the same stable value.
192	            for (Owner existing : this.clinicService.findAllOwners()) {
193	                if (collapse(existing.getLastName()).equals(normalizedLastName)
194	                    && normalizeAddress(existing.getAddress()).equals(normalizedAddress)
195	                    && !householdId.equals(existing.getHouseholdId())) {
196	                    existing.setHouseholdId(householdId);
197	                    this.clinicService.saveOwner(existing);
198	                }
199	            }
200	        } else {
201	            boolean householdInUse = this.clinicService.findAllOwners().stream()
202	                .anyMatch(existing -> collapse(existing.getLastName()).equals(normalizedLastName)
203	                    && normalizeAddress(existing.getAddress()).equals(normalizedAddress));
204	            if (householdInUse) {
205	                throw new DuplicateOwnerHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
206	            }
207	        }
208	        HttpHeaders headers = new HttpHeaders();
209	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
210	        owner.setAddress(normalizedAddress);
211	        owner.setTelephone(normalizedTelephone);
212	        owner.setEmail(normalizedEmail);
213	        owner.setHouseholdId(householdId);
214	        // Record how many existing owners (before this create) share this owner's first and last
215	        // name, compared case-insensitively. Computed against the current owners so the new owner
216	        // itself is never counted.
217	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
218	        // Persist the bulk-signup flag computed above so it is returned on subsequent reads.
219	        owner.setBulkSignupWarning(bulkSignupWarning);
220	        // Store the business-day-adjusted effective registration date computed above. This defaults
221	        // to the server's current date when none was supplied and rolls any weekend date forward to
222	        // the following Monday, so everything derived from it (e.g. the membership number's year
223	        // segment) uses the adjusted date.
224	        owner.setRegistrationDate(effectiveRegistrationDate);
225	        // Assign the customer code: '<CITY3>-<LAST3>-<NNNN>' where CITY3 is the upper-cased first
226	        // three letters of the city, LAST3 the upper-cased first three letters of the last name and
227	        // NNNN is a per-city 4-digit zero-padded sequence equal to one more than the number of
228	        // owners already in that city.
229	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
230	        this.clinicService.saveOwner(owner);
231	        // Emit an audit trail line for the successful create, carrying the owner id, the assigned
232	        // customer code and the effective registration date.
233	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
234	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
235	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
236	        headers.setLocation(UriComponentsBuilder.newInstance()
237	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
238	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
239	    }
240	
241	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
242	    @Override
243	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
244	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
245	        if (currentOwner == null) {
246	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
247	        }
248	        currentOwner.setAddress(ownerFieldsDto.getAddress());
249	        currentOwner.setCity(ownerFieldsDto.getCity());
250	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
251	        currentOwner.setLastName(ownerFieldsDto.getLastName());
252	        currentOwner.setTelephone(toE164(ownerFieldsDto.getTelephone()));
253	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
254	        this.clinicService.saveOwner(currentOwner);
255	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
256	    }
257	
258	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
259	    @Transactional
260	    @Override
261	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
262	        Owner owner = this.clinicService.findOwnerById(ownerId);
263	        if (owner == null) {
264	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
265	        }
266	        this.clinicService.deleteOwner(owner);
267	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
268	    }
269	
270	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
271	    @Override
272	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
273	        Owner owner = this.clinicService.findOwnerById(ownerId);
274	        if (owner == null) {
275	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
276	        }
277	        HttpHeaders headers = new HttpHeaders();
278	        Pet pet = petMapper.toPet(petFieldsDto);
279	        owner.setId(ownerId);
280	        pet.setOwner(owner);
281	        pet.getType().setName(null);
282	        this.clinicService.savePet(pet);
283	        PetDto petDto = petMapper.toPetDto(pet);
284	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
285	            .buildAndExpand(pet.getId()).toUri());
286	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
287	    }
288	
289	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
290	    @Override
291	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
292	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
293	        if (currentOwner != null) {
294	            Pet currentPet = this.clinicService.findPetById(petId);
295	            if (currentPet != null) {
296	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
297	                currentPet.setName(petFieldsDto.getName());
298	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
299	                this.clinicService.savePet(currentPet);
300	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
301	            }
302	        }
303	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
304	    }
305	
306	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
307	    @Override
308	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
309	        HttpHeaders headers = new HttpHeaders();
310	        Visit visit = visitMapper.toVisit(visitFieldsDto);
311	        Pet pet = new Pet();
312	        pet.setId(petId);
313	        visit.setPet(pet);
314	        this.clinicService.saveVisit(visit);
315	        VisitDto visitDto = visitMapper.toVisitDto(visit);
316	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
317	            .buildAndExpand(visit.getId()).toUri());
318	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
319	    }
320	
321	
322	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
323	    @Override
324	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
325	        Owner owner = this.clinicService.findOwnerById(ownerId);
326	        if (owner != null) {
327	            Pet pet = owner.getPet(petId);
328	            if (pet != null) {
329	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
330	            }
331	        }
332	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
333	    }
334	
335	    private static boolean isBlank(String value) {
336	        return value == null || value.trim().isEmpty();
337	    }
338	
339	    /**
340	     * Normalize an owner identity field for household-duplicate comparison: trim, collapse every
341	     * run of whitespace to a single space, and lower-case. Used so that last name and address are
342	     * compared case-insensitively with collapsed whitespace.
343	     */
344	    private static String collapse(String value) {
345	        if (value == null) {
346	            return "";
347	        }
348	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
349	    }
350	
351	    /**
352	     * Common street-type abbreviations expanded during address normalization.
353	     */
354	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
355	        "ST", "STREET",
356	        "RD", "ROAD",
357	        "AVE", "AVENUE");
358	
359	    /**
360	     * Normalize an owner address into its canonical stored/compared form: trim, collapse every run
361	     * of whitespace to a single space, upper-case, and expand common street-type abbreviations
362	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). Returns an empty string for
363	     * a {@code null} or blank input. The transformation is idempotent, so an already-normalized
364	     * address maps to itself.
365	     */
366	    private static String normalizeAddress(String value) {
367	        if (value == null) {
368	            return "";
369	        }
370	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
371	        if (collapsed.isEmpty()) {
372	            return "";
373	        }
374	        String[] tokens = collapsed.split(" ");
375	        StringBuilder sb = new StringBuilder(collapsed.length());
376	        for (int i = 0; i < tokens.length; i++) {
377	            if (i > 0) {
378	                sb.append(' ');
379	            }
380	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
381	        }
382	        return sb.toString();
383	    }
384	
385	    /**
386	     * Derive the stable household identifier shared by owners with the same normalized last name
387	     * and address. It is a deterministic function of those two values, so every member of a
388	     * household independently derives the same identifier: the first 12 upper-case hex characters
389	     * of {@code SHA-256(normalizedLastName + '\n' + normalizedAddress)}.
390	     */
391	    private static String householdId(String normalizedLastName, String normalizedAddress) {
392	        try {
393	            byte[] digest = MessageDigest.getInstance("SHA-256")
394	                .digest((normalizedLastName + "\n" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
395	            StringBuilder sb = new StringBuilder(digest.length * 2);
396	            for (byte b : digest) {
397	                sb.append(String.format("%02x", b));
398	            }
399	            return sb.substring(0, 12).toUpperCase();
400	        }
401	        catch (NoSuchAlgorithmException e) {
402	            throw new IllegalStateException("SHA-256 not available", e);
403	        }
404	    }
405	
406	    /**
407	     * Build the customer code for a new owner: {@code '<CITY3>-<LAST3>-<NNNN>'} where CITY3 is the
408	     * upper-cased first three letters of the city, LAST3 the upper-cased first three letters of the
409	     * last name and NNNN is a per-city 4-digit zero-padded sequence equal to one more than the
410	     * number of owners already in that city (e.g. {@code 'SYD-SMI-0007'}).
411	     */
412	    /**
413	     * Count the existing owners that share the given first and last name, compared
414	     * case-insensitively. Called before the new owner is saved, so the returned value reflects the
415	     * namesakes that already existed at creation time (the new owner itself is not included).
416	     */
417	    private int countNamesakes(String firstName, String lastName) {
418	        return (int) this.clinicService.findAllOwners().stream()
419	            .filter(existing -> existing.getFirstName() != null && existing.getLastName() != null)
420	            .filter(existing -> existing.getFirstName().equalsIgnoreCase(firstName)
421	                && existing.getLastName().equalsIgnoreCase(lastName))
422	            .count();
423	    }
424	
425	    /**
426	     * The maximum number of owners a single city may contain. Once a city holds this many owners a
427	     * request to create another owner in it is rejected as a conflict.
428	     */
429	    private static final int MAX_OWNERS_PER_CITY = 50;
430	
431	    /**
432	     * Count the existing owners registered in the given city, compared case-insensitively (as in
433	     * {@link #nextCustomerCode}). Called before the new owner is saved, so the returned value
434	     * reflects the owners that already existed at creation time.
435	     */
436	    private int countOwnersInCity(String city) {
437	        return (int) this.clinicService.findAllOwners().stream()
438	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
439	            .count();
440	    }
441	
442	    /**
443	     * The maximum number of owners that may be created on a single day. Once this many owners
444	     * already carry a given day's registration date, a request to create another owner that day is
445	     * rejected with a 429.
446	     */
447	    private static final int MAX_OWNERS_PER_DAY = 100;
448	
449	    /**
450	     * The number of owners that may be created on a single day before the bulk-signup warning is
451	     * flagged. Once more than this many owners already carry a given day's registration date, a
452	     * newly created owner is flagged with {@code bulkSignupWarning} set true.
453	     */
454	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
455	
456	    /**
457	     * Count the existing owners whose registration date is the given day. Called before the new
458	     * owner is saved, so the returned value reflects the owners that already existed at creation
459	     * time.
460	     */
461	    private int countOwnersRegisteredOn(LocalDate date) {
462	        return (int) this.clinicService.findAllOwners().stream()
463	            .filter(existing -> date.equals(existing.getRegistrationDate()))
464	            .count();
465	    }
466	
467	    /**
468	     * Roll a date forward onto a business day: a Saturday or Sunday is advanced to the following
469	     * Monday, while a weekday is returned unchanged. Used so the effective registration date (whether
470	     * supplied or defaulted) always falls on a business day.
471	     */
472	    private static LocalDate toBusinessDay(LocalDate date) {
473	        return switch (date.getDayOfWeek()) {
474	            case SATURDAY -> date.plusDays(2);
475	            case SUNDAY -> date.plusDays(1);
476	            default -> date;
477	        };
478	    }
479	
480	    private String nextCustomerCode(String city, String lastName) {
481	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
482	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
483	        long sequence = this.clinicService.findAllOwners().stream()
484	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
485	            .count() + 1L;
486	        return String.format("%s-%s-%04d", city3, last3, sequence);
487	    }
488	
489	    /**
490	     * Convert a raw telephone into E.164 form. Spaces, dashes and brackets are stripped. A leading
491	     * {@code '+'} with its country code is preserved; otherwise the Australian country code
492	     * {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the national digits.
493	     * The result must be a {@code '+'} followed by 8 to 15 digits, otherwise an
494	     * {@link InvalidOwnerFieldsException} is thrown so the request is rejected with a 400.
495	     */
496	    private static String toE164(String raw) {
497	        String cleaned = raw.trim().replaceAll("[\\s()\\-]", "");
498	        boolean hasCountryCode = cleaned.startsWith("+");
499	        String digits = hasCountryCode ? cleaned.substring(1) : cleaned;
500	        if (!digits.matches("\\d+")) {
501	            throw new InvalidOwnerFieldsException(List.of("telephone"));
502	        }
503	        if (!hasCountryCode) {
504	            if (digits.startsWith("0")) {
505	                digits = digits.substring(1);
506	            }
507	            digits = "61" + digits;
508	        }
509	        if (digits.length() < 8 || digits.length() > 15) {
510	            throw new InvalidOwnerFieldsException(List.of("telephone"));
511	        }
512	        return "+" + digits;
513	    }
514	
515	    /**
516	     * Pragmatic syntactic check for an email address: a non-empty local part, an {@code @},
517	     * and a domain with at least one dot-separated label, none of which contain whitespace or
518	     * a second {@code @}. This is deliberately permissive but rejects obviously malformed input.
519	     */
520	    private static final Pattern EMAIL_PATTERN =
521	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
522	
523	    /**
524	     * Validate and normalize an optional owner email. Returns {@code null} when no email was
525	     * supplied (the field is optional). When supplied it must be a syntactically valid address,
526	     * otherwise an {@link InvalidOwnerFieldsException} is thrown so the request is rejected with a
527	     * 400. A valid address is returned lower-cased.
528	     */
529	    private static String normalizeEmail(String email) {
530	        if (email == null || email.isEmpty()) {
531	            return null;
532	        }
533	        String trimmed = email.trim();
534	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
535	            throw new InvalidOwnerFieldsException(List.of("email"));
536	        }
537	        return trimmed.toLowerCase();
538	    }
539	}
